// ================================================================
// KONFIGURASI
// ================================================================
const PCT_ANCHOR    = 45;
const PCT_DIP       = 35;
const PCT_DEEP_DIP  = 25;

const DIP_THRESHOLD      = 3.0;
const DEEP_DIP_THRESHOLD = 5.0;
const TP1_PCT            = 2.0;
const TP2_PCT            = 4.0;
const COOLDOWN_MINUTES   = 60;
const TROY_OZ_TO_GRAM    = 31.1034768;

// ================================================================
// HELPER
// ================================================================
const formatIDR = (n) =>
  new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR',
    minimumFractionDigits: 0, maximumFractionDigits: 0
  }).format(Math.round(n));

const fmt = (n, d = 2) => Number(n).toFixed(d);

const nowUTC     = new Date();
const nowWITA    = new Date(nowUTC.getTime() + 8 * 60 * 60 * 1000);
const todayDate  = nowWITA.getDate();
const todayMonth = nowWITA.getMonth();
const todayYear  = nowWITA.getFullYear();
const timeLabel  = nowWITA.toLocaleString('id-ID', { timeZone: 'Asia/Makassar' });
const nowMs      = Date.now();
const CD_MS      = COOLDOWN_MINUTES * 60 * 1000;

const tanggalPanjang = nowWITA.toLocaleDateString('id-ID', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

// ================================================================
// ANCHOR DATE
// ================================================================
function getAnchorDate() {
  let anchorMonth, anchorYear;
  if (todayDate <= 25) {
    if (todayMonth === 0) { anchorMonth = 11; anchorYear = todayYear - 1; }
    else                  { anchorMonth = todayMonth - 1; anchorYear = todayYear; }
  } else {
    anchorMonth = todayMonth;
    anchorYear  = todayYear;
  }
  return new Date(anchorYear, anchorMonth, 25);
}

const anchorTarget    = getAnchorDate();
const anchorDateLabel = anchorTarget.toLocaleDateString('id-ID', {
  day: 'numeric', month: 'long', year: 'numeric'
});
const bulanSiklus = anchorTarget.toLocaleDateString('id-ID', {
  month: 'long', year: 'numeric'
});

// ================================================================
// PARSE GOOGLE SHEETS
// ================================================================
const rawText  = $('Baca Sheet INVEST EMAS').first().json.data;
const jsonText = rawText.replace(/^[^\(]+\(/, '').replace(/\);?\s*$/, '');
const gviz     = JSON.parse(jsonText);
const cols     = gviz.table.cols.map(c => c.label.trim());
const rows     = gviz.table.rows;

const COL = {
  anchorDate    : cols.indexOf('ANCHOR DATE'),
  anchorPrice   : cols.indexOf('ANCHOR PRICE'),
  anchorDeposit : cols.indexOf('ANCHOR DEPOSIT'),
  dipDate       : cols.indexOf('DIP BUY DATE'),
  dipPrice      : cols.indexOf('DIP BUY PRICE'),
  dipDeposit    : cols.indexOf('DIP BUY DEPOSIT'),
  deepDate      : cols.indexOf('DEEP DIP DATE'),
  deepPrice     : cols.indexOf('DEEP DIP PRICE'),
  deepDeposit   : cols.indexOf('DEEP DIP DEPOSIT'),
  totalDeposit  : cols.indexOf('TOTAL DEPOSIT'),
  totalBudget   : cols.indexOf('TOTAL BUDGET'),
  swingEntryAvg : cols.indexOf('SWING ENTRY AVG'),
  swingAmmo     : cols.indexOf('SWING AMMO IDR')
};

if (COL.anchorDate < 0 || COL.anchorPrice < 0) {
  throw new Error('Kolom ANCHOR DATE / ANCHOR PRICE tidak ditemukan.');
}

const getCellVal = (row, colIdx) => {
  if (colIdx < 0) return null;
  const cell = row.c[colIdx];
  return (cell && cell.v !== null && cell.v !== undefined) ? cell.v : null;
};

function parseGSheetDate(raw) {
  if (!raw) return null;
  if (typeof raw === 'string' && raw.startsWith('Date(')) {
    const p = raw.replace('Date(','').replace(')','').split(',').map(Number);
    return new Date(p[0], p[1], p[2]);
  }
  if (typeof raw === 'string' && raw.includes('/')) {
    const [d,m,y] = raw.split('/').map(Number);
    return new Date(y, m-1, d);
  }
  if (typeof raw === 'number') return new Date((raw - 25569) * 86400 * 1000);
  return null;
}

let anchorPriceUSD = null, anchorDeposit = null;
let dipPriceUSD    = null, dipDeposit    = null;
let deepPriceUSD   = null, deepDeposit   = null;
let totalBudgetIDR = null, totalDeposit  = null;
let swingEntryAvg  = null, swingAmmoIDR  = null;
let anchorFilled   = false, dipFilled = false, deepFilled = false;

for (const row of rows) {
  const rowDate = parseGSheetDate(getCellVal(row, COL.anchorDate));
  if (!rowDate) continue;
  if (
    rowDate.getFullYear() === anchorTarget.getFullYear() &&
    rowDate.getMonth()    === anchorTarget.getMonth()    &&
    rowDate.getDate()     === anchorTarget.getDate()
  ) {
    anchorPriceUSD = Number(getCellVal(row, COL.anchorPrice))   || null;
    anchorDeposit  = Number(getCellVal(row, COL.anchorDeposit)) || null;
    dipPriceUSD    = COL.dipPrice    >= 0 ? Number(getCellVal(row, COL.dipPrice))    || null : null;
    dipDeposit     = COL.dipDeposit  >= 0 ? Number(getCellVal(row, COL.dipDeposit))  || null : null;
    deepPriceUSD   = COL.deepPrice   >= 0 ? Number(getCellVal(row, COL.deepPrice))   || null : null;
    deepDeposit    = COL.deepDeposit >= 0 ? Number(getCellVal(row, COL.deepDeposit)) || null : null;
    totalBudgetIDR = COL.totalBudget >= 0 ? Number(getCellVal(row, COL.totalBudget)) || null : null;
    totalDeposit   = COL.totalDeposit >= 0 ? Number(getCellVal(row, COL.totalDeposit)) || null : null;
    swingEntryAvg  = COL.swingEntryAvg >= 0 ? Number(getCellVal(row, COL.swingEntryAvg)) || null : null;
    swingAmmoIDR   = COL.swingAmmo  >= 0 ? Number(getCellVal(row, COL.swingAmmo))   || null : null;
    anchorFilled   = !!(anchorPriceUSD && anchorPriceUSD > 0);
    dipFilled      = !!(dipPriceUSD    && dipPriceUSD    > 0);
    deepFilled     = !!(deepPriceUSD   && deepPriceUSD   > 0);
    break;
  }
}

let fallbackAnchorUSD = anchorPriceUSD;
if (!fallbackAnchorUSD) {
  for (let i = rows.length - 1; i >= 0; i--) {
    const val = Number(getCellVal(rows[i], COL.anchorPrice));
    if (!isNaN(val) && val > 0) { fallbackAnchorUSD = val; break; }
  }
}

// ================================================================
// HARGA SEKARANG
// ================================================================
const currentPaxgUSD = Number($('Ambil Harga PAXG').first().json.price);
const usdtIdr        = Number($('Ambil Kurs USDT/IDR').first().json.price);
if (isNaN(currentPaxgUSD)) throw new Error('Harga PAXG tidak valid');
if (isNaN(usdtIdr))        throw new Error('Kurs USDT/IDR tidak valid');

const paxgIdrPerGram = (currentPaxgUSD / TROY_OZ_TO_GRAM) * usdtIdr;

// ================================================================
// BUDGET
// ================================================================
const safeTotal = totalBudgetIDR || 4000000;
const safeAmmo  = swingAmmoIDR   || 10000000;

const budgetAnchor  = safeTotal * (PCT_ANCHOR   / 100);
const budgetDip     = safeTotal * (PCT_DIP      / 100);
const budgetDeepDip = safeTotal * (PCT_DEEP_DIP / 100);

// ================================================================
// DROP & GAIN %
// ================================================================
const dropPct = fallbackAnchorUSD
  ? ((fallbackAnchorUSD - currentPaxgUSD) / fallbackAnchorUSD) * 100
  : null;

const gainPct = (swingEntryAvg && swingEntryAvg > 0)
  ? ((currentPaxgUSD - swingEntryAvg) / swingEntryAvg) * 100
  : null;

// ================================================================
// STATIC DATA
// ================================================================
const sd = $getWorkflowStaticData('global');

const dipDraftKey  = `draftDip_${anchorTarget.getFullYear()}_${anchorTarget.getMonth()}`;
const deepDraftKey = `draftDeep_${anchorTarget.getFullYear()}_${anchorTarget.getMonth()}`;
const tp1DraftKey  = `draftTP1_${anchorTarget.getFullYear()}_${anchorTarget.getMonth()}_${Math.floor(nowMs/(24*60*60*1000))}`;
const tp2DraftKey  = `draftTP2_${anchorTarget.getFullYear()}_${anchorTarget.getMonth()}_${Math.floor(nowMs/(24*60*60*1000))}`;

// ================================================================
// HEADER HARGA
// ================================================================
const headerPrice =
  `🕐 ${timeLabel} WITA\n` +
  `💹 PAXG : $${fmt(currentPaxgUSD)} / troy oz\n` +
  `💱 Kurs : ${formatIDR(usdtIdr)} / USDT\n` +
  `💵 /gram: ${formatIDR(paxgIdrPerGram)}\n`;

const budgetBlock =
  `📊 Budget ${bulanSiklus}: ${formatIDR(safeTotal)}\n` +
  `   Anchor  (${PCT_ANCHOR}%): ${formatIDR(budgetAnchor)}\n` +
  `   Dip     (${PCT_DIP}%): ${formatIDR(budgetDip)}\n` +
  `   Deep    (${PCT_DEEP_DIP}%): ${formatIDR(budgetDeepDip)}\n`;

// ================================================================
// ALERTS
// ================================================================
const alerts = [];

// ─── ANCHOR REMINDER ────────────────────────────────────────────
if (todayDate === 25 && !anchorFilled && (nowMs - (sd.lastAnchorReminder||0)) >= 60*60*1000) {
  sd.lastAnchorReminder = nowMs;
  alerts.push({
    type: 'ANCHOR_REMINDER',
    message:
      `📌 *REMINDER — ANCHOR BUY BELUM DILAKUKAN*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `${headerPrice}` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `📅 Anchor date: *${anchorDateLabel}*\n` +
      `⚠️ ANCHOR PRICE di sheet masih kosong!\n\n` +
      `${budgetBlock}` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `👉 Beli anchor sekarang & isi sheet!`
  });
}

// ─── DIP BUY ALERT ──────────────────────────────────────────────
if (dropPct !== null && dropPct >= DIP_THRESHOLD && dropPct < DEEP_DIP_THRESHOLD && (nowMs - (sd.lastDipAlert||0)) > CD_MS) {
  sd.lastDipAlert = nowMs;
  alerts.push({
    type: 'DIP_BUY',
    message:
      `⚠️ *DIP BUY ALERT (≥${DIP_THRESHOLD}%)*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `${headerPrice}` +
      `📅 Anchor : ${anchorDateLabel}\n` +
      `🎯 Anchor : $${fmt(fallbackAnchorUSD)}\n` +
      `📉 Turun  : *${fmt(dropPct)}%* dari anchor\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `💰 Alokasi Dip (${PCT_DIP}%): *${formatIDR(budgetDip)}*\n` +
      `${budgetBlock}` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `✅ Eksekusi → isi sheet → draft thread otomatis terkirim`
  });
}

// ─── DEEP DIP ALERT ─────────────────────────────────────────────
if (dropPct !== null && dropPct >= DEEP_DIP_THRESHOLD && (nowMs - (sd.lastDeepAlert||0)) > CD_MS) {
  sd.lastDeepAlert = nowMs;
  alerts.push({
    type: 'DEEP_DIP',
    message:
      `🚨 *DEEP DIP ALERT (≥${DEEP_DIP_THRESHOLD}%) — BELI SEKARANG!*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `${headerPrice}` +
      `📅 Anchor : ${anchorDateLabel}\n` +
      `🎯 Anchor : $${fmt(fallbackAnchorUSD)}\n` +
      `📉 Turun  : *${fmt(dropPct)}%* dari anchor\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `💰 Alokasi Deep (${PCT_DEEP_DIP}%): *${formatIDR(budgetDeepDip)}*\n` +
      `${budgetBlock}` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `⚡ Eksekusi → isi sheet → draft thread otomatis terkirim`
  });
}

// ─── TP1 ALERT ──────────────────────────────────────────────────
if (gainPct !== null && gainPct >= TP1_PCT && gainPct < TP2_PCT && (nowMs - (sd.lastTP1||0)) > CD_MS) {
  sd.lastTP1 = nowMs;
  alerts.push({
    type: 'TP1',
    message:
      `✅ *TAKE PROFIT 1 — JUAL 50% POSISI*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `${headerPrice}` +
      `📈 Entry avg : $${fmt(swingEntryAvg)}\n` +
      `📈 Gain      : *+${fmt(gainPct)}%* dari entry\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `💰 Jual 50% posisi sekarang\n` +
      `🎯 TP2 target: $${fmt(swingEntryAvg * (1 + TP2_PCT/100))} (+${TP2_PCT}%)\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `✅ Eksekusi → isi sheet → draft thread otomatis terkirim`
  });
}

// ─── TP2 ALERT ──────────────────────────────────────────────────
if (gainPct !== null && gainPct >= TP2_PCT && (nowMs - (sd.lastTP2||0)) > CD_MS) {
  sd.lastTP2 = nowMs;
  alerts.push({
    type: 'TP2',
    message:
      `🎉 *TAKE PROFIT 2 — JUAL SEMUA POSISI!*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `${headerPrice}` +
      `📈 Entry avg : $${fmt(swingEntryAvg)}\n` +
      `📈 Gain      : *+${fmt(gainPct)}%* dari entry\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `💰 Jual SEMUA sisa posisi\n` +
      `🔄 Kosongkan SWING ENTRY AVG di sheet setelah jual\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `🎉 Eksekusi → isi sheet → draft thread otomatis terkirim`
  });
}

// ================================================================
// DRAFT THREAD — kalimat posting siap publish
// ================================================================

// ─── DRAFT DIP BUY ──────────────────────────────────────────────
if (dipFilled && !sd[dipDraftKey]) {
  sd[dipDraftKey] = true;
  const actualDrop = ((fallbackAnchorUSD - dipPriceUSD) / fallbackAnchorUSD * 100);
  const gramDip    = dipDeposit ? dipDeposit / ((dipPriceUSD / TROY_OZ_TO_GRAM) * usdtIdr) : null;
  const paxgIdrDip = (dipPriceUSD / TROY_OZ_TO_GRAM) * usdtIdr;

  alerts.push({
    type: 'DRAFT_DIP',
    message:
      `📝 *DRAFT THREAD — SIAP PUBLISH*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Salin teks di bawah ini ke Thread / X / sosmed:\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +

      `📅 Update Investasi Emas — ${tanggalPanjang}\n\n` +

      `Hari ini saya mengeksekusi *Dip Buy* pada instrumen PAXG (PAX Gold).\n\n` +

      `Harga emas terkoreksi ${fmt(actualDrop)}% dari harga referensi anchor bulan ini ` +
      `($${fmt(fallbackAnchorUSD)}/troy oz), sehingga saya memanfaatkan momentum ini ` +
      `untuk menambah posisi sesuai strategi DCA 3-tier yang saya jalankan.\n\n` +

      `📊 Detail Transaksi:\n` +
      `• Instrumen  : PAXG (1 PAXG = 1 troy oz emas)\n` +
      `• Harga beli : $${fmt(dipPriceUSD)}/troy oz (${formatIDR(paxgIdrDip)}/gram)\n` +
      `• Deposit    : ${formatIDR(dipDeposit)}\n` +
      (gramDip ? `• Estimasi   : ~${fmt(gramDip, 4)} gram emas\n` : '') +
      `• Koreksi    : −${fmt(actualDrop)}% dari anchor\n\n` +

      `📐 Tentang Strategi:\n` +
      `Saya menggunakan strategi DCA 3-tier untuk akumulasi emas digital (PAXG):\n` +
      `• Anchor Buy (${PCT_ANCHOR}%) — rutin setiap tanggal 25\n` +
      `• Dip Buy (${PCT_DIP}%)    — saat harga turun ≥3% dari anchor\n` +
      `• Deep Dip (${PCT_DEEP_DIP}%)  — saat harga turun ≥5% dari anchor\n\n` +

      `PAXG dipilih karena didukung emas fisik, spread hanya ~0,3%, dan dapat dikonversi ke emas batangan fisik sewaktu-waktu.\n\n` +

      `#Emas #PAXG #DipBuy #InvestasiEmas #DCA`
  });
}

// ─── DRAFT DEEP DIP ─────────────────────────────────────────────
if (deepFilled && !sd[deepDraftKey]) {
  sd[deepDraftKey] = true;
  const actualDrop = ((fallbackAnchorUSD - deepPriceUSD) / fallbackAnchorUSD * 100);
  const gramDeep   = deepDeposit ? deepDeposit / ((deepPriceUSD / TROY_OZ_TO_GRAM) * usdtIdr) : null;
  const paxgIdrDeep = (deepPriceUSD / TROY_OZ_TO_GRAM) * usdtIdr;

  alerts.push({
    type: 'DRAFT_DEEP',
    message:
      `📝 *DRAFT THREAD — SIAP PUBLISH*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Salin teks di bawah ini ke Thread / X / sosmed:\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +

      `📅 Update Investasi Emas — ${tanggalPanjang}\n\n` +

      `Hari ini saya mengeksekusi *Deep Dip Buy* pada instrumen PAXG (PAX Gold).\n\n` +

      `Koreksi harga emas mencapai ${fmt(actualDrop)}% dari anchor bulan ini ` +
      `($${fmt(fallbackAnchorUSD)}/troy oz) — ini adalah level deep dip yang saya tunggu ` +
      `untuk mengalokasikan sisa amunisi beli sesuai strategi.\n\n` +

      `📊 Detail Transaksi:\n` +
      `• Instrumen  : PAXG (1 PAXG = 1 troy oz emas)\n` +
      `• Harga beli : $${fmt(deepPriceUSD)}/troy oz (${formatIDR(paxgIdrDeep)}/gram)\n` +
      `• Deposit    : ${formatIDR(deepDeposit)}\n` +
      (gramDeep ? `• Estimasi   : ~${fmt(gramDeep, 4)} gram emas\n` : '') +
      `• Koreksi    : −${fmt(actualDrop)}% dari anchor\n\n` +

      `📐 Tentang Strategi:\n` +
      `Strategi DCA 3-tier yang saya jalankan:\n` +
      `• Anchor Buy (${PCT_ANCHOR}%) — rutin setiap tanggal 25\n` +
      `• Dip Buy (${PCT_DIP}%)    — harga turun ≥3% dari anchor\n` +
      `• Deep Dip (${PCT_DEEP_DIP}%)  — harga turun ≥5% dari anchor\n\n` +

      `Setelah 3 tier terpenuhi, tidak ada pembelian tambahan di siklus ini. ` +
      `Posisi di-hold hingga target take profit tercapai atau siklus berikutnya dimulai.\n\n` +

      `#Emas #PAXG #DeepDip #InvestasiEmas #DCA`
  });
}

// ─── DRAFT TP1 ──────────────────────────────────────────────────
if (gainPct !== null && gainPct >= TP1_PCT && !sd[tp1DraftKey]) {
  sd[tp1DraftKey] = true;
  const profitPct  = gainPct - 0.6; // net setelah spread
  const tp2Target  = swingEntryAvg * (1 + TP2_PCT / 100);

  alerts.push({
    type: 'DRAFT_TP1',
    message:
      `📝 *DRAFT THREAD — SIAP PUBLISH*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Salin teks di bawah ini ke Thread / X / sosmed:\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +

      `📅 Update Investasi Emas — ${tanggalPanjang}\n\n` +

      `Hari ini saya merealisasikan *Take Profit pertama (TP1)* pada posisi swing PAXG saya.\n\n` +

      `Harga telah naik +${fmt(gainPct)}% dari rata-rata harga beli saya ` +
      `($${fmt(swingEntryAvg)}/troy oz), sehingga saya memutuskan untuk menjual 50% posisi ` +
      `di harga $${fmt(currentPaxgUSD)}/troy oz sesuai rencana awal.\n\n` +

      `📊 Detail:\n` +
      `• Entry avg  : $${fmt(swingEntryAvg)}/troy oz\n` +
      `• Harga TP1  : $${fmt(currentPaxgUSD)}/troy oz\n` +
      `• Gain gross : +${fmt(gainPct)}%\n` +
      `• Net profit : ~+${fmt(profitPct)}% (setelah spread ~0,3% × 2)\n` +
      `• Aksi       : Jual 50% posisi ✅\n` +
      `• Sisa hold  : 50% menunggu TP2\n\n` +

      `🎯 Target TP2: $${fmt(tp2Target)}/troy oz (+${TP2_PCT}% dari entry)\n\n` +

      `📐 Strategi ini adalah bagian dari *Swing PAXG dengan Floor Fisik* — ` +
      `trading di atas 40 gram emas fisik yang tidak saya sentuh, ` +
      `menggunakan amunisi terpisah yang berputar setiap siklus.\n\n` +

      `#Emas #PAXG #TakeProfit #SwingTrading #InvestasiEmas`
  });
}

// ─── DRAFT TP2 ──────────────────────────────────────────────────
if (gainPct !== null && gainPct >= TP2_PCT && !sd[tp2DraftKey]) {
  sd[tp2DraftKey] = true;
  const profitPct = gainPct - 0.6;

  alerts.push({
    type: 'DRAFT_TP2',
    message:
      `📝 *DRAFT THREAD — SIAP PUBLISH*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Salin teks di bawah ini ke Thread / X / sosmed:\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +

      `📅 Update Investasi Emas — ${tanggalPanjang}\n\n` +

      `Hari ini satu siklus swing PAXG saya selesai dengan merealisasikan *Take Profit kedua (TP2)* — full exit dari posisi.\n\n` +

      `Harga mencapai +${fmt(gainPct)}% dari rata-rata entry saya ` +
